9.1 Data Sources

# 1. Results data from extraction
results_file &lt;- "results/results.csv"
if (!file.exists(results_file)) results_file &lt;- "results/results_flat.csv"
if (!file.exists(results_file)) results_file &lt;- "results_flat.csv"
results &lt;- read_csv(results_file, show_col_types = FALSE)

# 2. LAD and Transport Authority geometry/names from uktransportauthorities
geojson_file &lt;- "data/transport_authorities_2026.geojson"
if (!file.exists(geojson_file)) geojson_file &lt;- "tda/transport_authorities_2026.geojson"
if (!file.exists(geojson_file)) geojson_file &lt;- "transport_authorities_2026.geojson"

if (file.exists(geojson_file)) {
    ltas &lt;- sf::read_sf(geojson_file)
} else {
    ltas &lt;- sf::read_sf("https://raw.githubusercontent.com/itsleeds/uktransportauthorities/refs/heads/main/transport_authorities_2026.geojson")
}

# 3. Historical ATF Allocations (2020/21 - 2024/25)
atf_file &lt;- "data/atf_table_aggregated.csv"
if (!file.exists(atf_file)) atf_file &lt;- "tda/atf_table_aggregated.csv"
if (!file.exists(atf_file)) atf_file &lt;- "scripts/atf_table_aggregated.csv"
if (!file.exists(atf_file)) atf_file &lt;- "atf_table_aggregated.csv"

if (file.exists(atf_file)) {
    atf &lt;- read_csv(atf_file, show_col_types = FALSE)
} else {
    atf &lt;- read_csv("https://raw.githubusercontent.com/itsleeds/uktransportauthorities/refs/heads/main/atf_table_aggregated.csv", show_col_types = FALSE)
}

# 4. Future ATF Multi-Year Allocations (2026 - 2030)
future_file &lt;- "data/lad_active_travel_allocations.csv"
if (!file.exists(future_file)) future_file &lt;- "tda/lad_active_travel_allocations.csv"
if (!file.exists(future_file)) future_file &lt;- "lad_active_travel_allocations.csv"

if (file.exists(future_file)) {
    atf_future &lt;- read_csv(future_file, show_col_types = FALSE)
} else {
    atf_future &lt;- read_csv("https://raw.githubusercontent.com/itsleeds/uktransportauthorities/refs/heads/main/lad_active_travel_allocations.csv", show_col_types = FALSE)
}

9.2 Entity Reconciliation & Name Matching
To ensure accurate joins between LCWIP reports and funding allocations, local authority names are cleaned and matched using Jaro-Winkler string distance with manual alias rules for reconfigured unitary and combined authorities.

# Extract unique authority names from extraction results
results_names &lt;- results |&gt;
    select(local_authority_name, combined_authority_name) |&gt;
    mutate(name = ifelse(
        !is.na(local_authority_name), 
        local_authority_name, 
        combined_authority_name
    )) |&gt;
    distinct(name) |&gt;
    arrange(name) |&gt;
    filter(!is.na(name))

# Extract names from LTAs and unpack JSON lookup
ltas_names &lt;- ltas |&gt;
    st_drop_geometry() |&gt;
    select(name, lad_lookup) |&gt;
    arrange(name) |&gt;
    rename(name_lookup = lad_lookup)

ltas_lookup_names &lt;- ltas_names |&gt;
    mutate(name_lookup = map(
        name_lookup, 
        ~ fromJSON(.x)$lad_name
    )) |&gt;
    select(name, name_lookup) |&gt;
    unnest(name_lookup)

ltas_lookup_names &lt;- bind_rows(
    ltas_lookup_names,
    ltas_lookup_names |&gt;
        distinct(name) |&gt;
        filter(!name %in% ltas_lookup_names$name_lookup) |&gt;
        mutate(name_lookup = name)
)

# Standardise names by stripping council boilerplate
results_names &lt;- results_names |&gt;
    mutate(name_clean = name |&gt;
        str_remove_all("(?i)city") |&gt;
        str_remove_all("(?i)councils") |&gt;
        str_remove_all("(?i)council") |&gt;
        str_remove_all("Borough") |&gt;
        str_remove_all("(?i)district") |&gt;
        str_remove_all("(?i)county") |&gt;
        str_remove_all("(?i)of") |&gt;
        str_remove_all("(?i)the") |&gt;
        str_remove_all("(?i) and") |&gt;
        str_remove_all("(?i)royal") |&gt;
        str_remove_all("(?i)combined authority") |&gt;
        str_remove_all("(?i)metropolitan") |&gt;
        str_remove_all("(?i)(national guidance)") |&gt;
        str_remove_all("(?i)&") |&gt;
        str_remove_all("(?i),") |&gt;
        str_remove_all("(?i)/") |&gt;
        str_squish()
    )

# Add manual aliases for known boundary reconfigurations
manual_aliases_ltas &lt;- tibble(
    name = c(
        "Kent",
        "West Yorkshire Combined Authority",
        "Bournemouth, Christchurch and Poole",
        "West of England Combined Authority",
        "Leicestershire",
        "Norfolk",
        "East Midlands Combined Authority",
        "North East Combined Authority",
        "East Riding of Yorkshire",
        "West Yorkshire Combined Authority",
        "Liverpool City Region Combined Authority",
        "Leicestershire",
        "Lancashire",
        "Leicestershire"
    ),
    name_lookup = c(
        "Faversham Town",
        "West Yorkshire",
        "BCP",
        "Bath North East Somerset Bristol South Gloucestershire North Somerset",
        "Blaby",
        "Broads Authority",
        "Derby Derbyshire Nottingham Nottinghamshire",
        "Durham",
        "Hull",
        "Leeds West Yorkshire",
        "Liverpool Region (LCRCA) in partnership with Halton Knowsley Liverpool Sefton St Helens Wirral",
        "North West Leicestershire",
        "Preston South Ribble Chorley",
        "Rutland"
    )
)

ltas_lookup_names &lt;- bind_rows(ltas_lookup_names, manual_aliases_ltas) |&gt;
    distinct(name, name_lookup, .keep_all = TRUE) |&gt;
    arrange(name, name_lookup)

# String distance fuzzy matching (Jaro-Winkler)
results_names &lt;- results_names |&gt;
    mutate(
        match_index = amatch(
            name_clean,
            ltas_lookup_names$name_lookup,
            method = "jw",
            maxDist = 0.25
        ),
        matched_name = ifelse(!is.na(match_index), ltas_lookup_names$name_lookup[match_index], NA_character_),
        ltas_name = ifelse(!is.na(match_index), ltas_lookup_names$name[match_index], NA_character_)
    )

9.3 ATF Name Harmonisation

# Clean historical ATF table
atf &lt;- atf |&gt; filter(name != "Total")
atf_names &lt;- atf |&gt;
    mutate(name = case_when(
        name == "West Midlands ITA" ~ "West Midlands Combined Authority",
        name == "North East Joint Transport Committee" ~ "North East Combined Authority",
        TRUE ~ name
    ))

# Clean future allocations & aggregate East Midlands Combined County Authority
emca_la_list &lt;- c(
    "Derby", "Derbyshire", "Nottingham", "Nottinghamshire", 
    "Leicester", "Leicestershire", "North East Lincolnshire", 
    "North Lincolnshire", "Lincolnshire", "Rutland"
)

emca_la &lt;- atf_future |&gt;
    filter(name %in% emca_la_list) |&gt;
    summarise(across(where(is.numeric), sum, na.rm = TRUE)) |&gt;
    mutate(
        name = "East Midlands Combined Authority", 
        name_atf = "East Midlands Combined County Authority"
    )

atf_future_names &lt;- atf_future |&gt;
    filter(!name %in% emca_la_list) |&gt;
    bind_rows(emca_la) |&gt;
    distinct(name, .keep_all = TRUE) |&gt;
    arrange(name)

9.4 Integrated Metric Construction
We aggregate document observations, depth-of-use scores, desire-line usage, and total funding amounts:

analysis &lt;- ltas_lookup_names |&gt;
    select(name) |&gt;
    distinct(name) |&gt;
    arrange(name)

results_analysis &lt;- results |&gt;
    left_join(
        results_names |&gt; select(local_authority_name = name, ltas_name),
        by = "local_authority_name"
    )

analysis_data &lt;- analysis |&gt;
    left_join(
        results_analysis |&gt;
            mutate(pct_usage_depth = parse_number(as.character(pct_usage_depth))) |&gt;
            group_by(ltas_name) |&gt;
            summarise(
                n_observations = n(),
                n_mentions_pct = sum(n_mentions_pct, na.rm = TRUE),
                pct_usage_depth_1 = sum(pct_usage_depth == 1, na.rm = TRUE),
                pct_usage_depth_2 = sum(pct_usage_depth == 2, na.rm = TRUE),
                pct_usage_depth_3 = sum(pct_usage_depth == 3, na.rm = TRUE),
                n_pct_desire_lines_used = sum(pct_desire_lines_used, na.rm = TRUE)
            ),
        by = c("name" = "ltas_name")
    ) |&gt;
    left_join(
        atf_names |&gt; select(name, atf20_21, atf21_22, atf22_23, atf23_24, atf24_25),
        by = "name"
    ) |&gt;
    left_join(
        atf_future_names |&gt; select(name, cdel_per_year_4yr, rdel_per_year_3yr, total_over_4yr),
        by = "name"
    ) |&gt;
    mutate(across(
        c(atf20_21, atf21_22, atf22_23, atf23_24, atf24_25, cdel_per_year_4yr, rdel_per_year_3yr, total_over_4yr),
        ~ {
            x &lt;- stringr::str_squish(as.character(.x))
            x[stringr::str_detect(x, stringr::regex("^invalid\\s*number$", ignore_case = TRUE))] &lt;- NA_character_
            readr::parse_number(x)
        }
    ))

funding_5yr_cols &lt;- c("atf20_21", "atf21_22", "atf22_23", "atf23_24", "atf24_25")

analysis_metrics &lt;- analysis_data |&gt;
    mutate(
        n_observations = replace_na(n_observations, 0),
        n_mentions_pct = replace_na(n_mentions_pct, 0),
        n_pct_desire_lines_used = replace_na(n_pct_desire_lines_used, 0),
        pct_usage_depth_1 = replace_na(pct_usage_depth_1, 0),
        pct_usage_depth_2 = replace_na(pct_usage_depth_2, 0),
        pct_usage_depth_3 = replace_na(pct_usage_depth_3, 0),
        n_depth_scored = pct_usage_depth_1 + pct_usage_depth_2 + pct_usage_depth_3,
        depth_score_mean = if_else(
            n_depth_scored &gt; 0,
            (1 * pct_usage_depth_1 + 2 * pct_usage_depth_2 + 3 * pct_usage_depth_3) / n_depth_scored,
            NA_real_
        ),
        total_over_5yr = if_else(
            rowSums(!is.na(across(all_of(funding_5yr_cols)))) &gt; 0,
            rowSums(across(all_of(funding_5yr_cols)), na.rm = TRUE),
            NA_real_
        ),
        pct_mention_rate = if_else(n_observations &gt; 0, n_mentions_pct / n_observations, NA_real_),
        desire_lines_rate = if_else(n_observations &gt; 0, n_pct_desire_lines_used / n_observations, NA_real_)
    )
